import 'package:flutter/material.dart';
void main()=>runApp(const RecipeOrganizerApp());
class RecipeOrganizerApp extends StatelessWidget { const RecipeOrganizerApp({super.key}); @override Widget build(BuildContext context)=>const MaterialApp(debugShowCheckedModeBanner:false,home:RecipeHome()); }
class RecipeHome extends StatefulWidget { const RecipeHome({super.key}); @override State<RecipeHome> createState()=>_RecipeHomeState(); }
class _RecipeHomeState extends State<RecipeHome> { static const lavender=Color(0xFFB57EDC); int bottomIndex=0; String activeCategory='Home'; final int savedCount=3; final bottomTitles=['Home','Search','Saved']; final bottomIcons=[Icons.home,Icons.search,Icons.bookmark]; final categories=['Breakfast','Lunch','Dinner','Favorites']; final categoryIcons=[Icons.free_breakfast,Icons.lunch_dining,Icons.dinner_dining,Icons.favorite]; void selectCategory(String category){setState(()=>activeCategory=category);Navigator.pop(context);} void selectBottom(int index){setState((){bottomIndex=index;activeCategory=bottomTitles[index];});} @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(activeCategory),actions:[Stack(alignment:Alignment.center,children:[IconButton(icon:const Icon(Icons.bookmark),onPressed:()=>selectBottom(2)),if(savedCount>0)Positioned(right:6,top:6,child:Container(padding:const EdgeInsets.all(3),decoration:const BoxDecoration(color:Colors.red,shape:BoxShape.circle),constraints:const BoxConstraints(minWidth:16,minHeight:16),child:Text('$savedCount',style:const TextStyle(color:Colors.white,fontSize:10),textAlign:TextAlign.center)))]),IconButton(icon:const Icon(Icons.settings),onPressed:(){})]),drawer:Drawer(child:ListView(padding:EdgeInsets.zero,children:[const DrawerHeader(decoration:BoxDecoration(color:lavender),child:CircleAvatar(radius:28,backgroundColor:Colors.white,child:Icon(Icons.person,size:32,color:lavender))),for(int i=0;i<categories.length;i++)ListTile(leading:Icon(categoryIcons[i],color:activeCategory==categories[i]?lavender:null),title:Text(categories[i],style:TextStyle(color:activeCategory==categories[i]?lavender:null,fontWeight:activeCategory==categories[i]?FontWeight.bold:FontWeight.normal)),onTap:()=>selectCategory(categories[i]))])),body:Center(child:Text('$activeCategory recipes',style:const TextStyle(fontSize:24))),floatingActionButton:FloatingActionButton(onPressed:()=>ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Add recipe'))),backgroundColor:lavender,child:const Icon(Icons.add)),bottomNavigationBar:BottomNavigationBar(currentIndex:bottomIndex,selectedItemColor:lavender,onTap:selectBottom,items:[for(int i=0;i<bottomTitles.length;i++)BottomNavigationBarItem(icon:Icon(bottomIcons[i]),label:bottomTitles[i])])); }
